{
  "concepts": [
    {
      "conditions": [],
      "definition": "An ordered proving surface showing the exercised feature or use-case boundary, the test-case sequence and expected outcomes at significant steps, making operational meaning inspectable. Declared scenarios and use cases expose operational boundaries, sequences, actors, controls and outcomes and are the preferred source for identifying significant code and control paths.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 265,
          "quote": "A scenario bundle shows the feature or use-case boundary being exercised,\nthe test-case sequence that proves it, and the outcomes expected at each\nsignificant step. It is the layer that makes operational meaning\ninspectable (P6).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F4.%20Scenario%20bundle",
          "start_line": 262
        }
      ],
      "key": "scenario_bundle",
      "label": "Scenario bundle"
    },
    {
      "conditions": [
        "The system has an installable or runnable development form."
      ],
      "definition": "The decisive proving lane exercises an installed development version as an independent project or externalised target.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 279,
          "quote": "Where a system has an installable or runnable development form, the\ndecisive proving lane runs against an installed development version as if\nit were an independent project or an externalised target, not only against\nthe source tree in place (P6, P3).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F5.%20Installed%20dev%20proof",
          "start_line": 276
        }
      ],
      "key": "installed_dev_proof",
      "label": "Installed development proof"
    },
    {
      "conditions": [],
      "definition": "Claim-relative meaningful paths deliberately named and exercised by the proving surface. Relevant paths usually include success, fail-closed or rejection, boundary or control, integration or dispatch or transport, and recovery or retry or replay.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 293,
          "quote": "The proving surface declares and exercises the significant paths for the\nbehaviour being claimed (P6, P2).\nExhaustive proof does not mean every possible branch in every file; it\nmeans the project names the meaningful paths and proves them\nintentionally.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F6.%20Significant%20path%20coverage",
          "start_line": 289
        }
      ],
      "key": "significant_paths",
      "label": "Significant paths"
    },
    {
      "conditions": [
        "Governing frame configuration or admitted work authority selects testing frames for a Product promotion, closure or release-assurance claim."
      ],
      "definition": "A claim-relative testing configuration ordinarily containing four distinct frames: user acceptance, end to end, integration and unit. Availability in this member does not activate the set or its supporting sections 8–13.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 306,
          "quote": "## 7. Product testing frame set",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set",
          "start_line": 306
        },
        {
          "end_line": 345,
          "quote": "Where the governing frame configuration (PRODUCT_DEFINITION §7) or the\nadmitted work authority selects testing frames for a Product promotion,\nclosure or release-assurance claim, testing is configured as a\nclaim-relative set of testing frames. Placement in this member makes the\nset, and the law of §8 to §13 that serves it, available; it adopts nothing,\nand each activation is decided by ACTIVATION §1 (Applicability).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FThe%20set",
          "start_line": 340
        }
      ],
      "key": "product_testing_frame_set",
      "label": "Product testing frame set"
    },
    {
      "conditions": [],
      "definition": "A frame whose evaluation executes or observes a declared subject to discriminate one exact claim using an explicit oracle, evidence population, path boundary and falsification condition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 313,
          "quote": "A testing frame is a frame (REFERENCE_FRAME §1) whose evaluation executes\nor observes a declared subject to discriminate one exact claim through an\nexplicit oracle, evidence population, path boundary and falsification\ncondition.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 310
        }
      ],
      "key": "testing_frame",
      "label": "Testing frame"
    },
    {
      "conditions": [],
      "definition": "The declared ordinary causal composition from a supported user or public entry through the exact selected interfaces, owners, state transitions, effects, persistence and recovery boundaries to the outcome projection required by the Product claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 322,
          "quote": "An authoritative Product path is the declared ordinary causal composition\nfrom a supported user or public entry, through the exact selected\ninterfaces, owners, state transitions, effects, persistence and recovery\nboundaries, to the outcome projection the Product claim requires.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 319
        }
      ],
      "key": "authoritative_product_path",
      "label": "Authoritative Product path"
    },
    {
      "conditions": [],
      "definition": "The claim-relative population of independent dimensions and interactions whose combinations can change an outcome, violate an invariant, select another authority path or expose failure. Unit dimensions include module-owned public-contract laws, algebraic operators, calculation regimes, states, transitions, boundary classes and failures; cross-participant interface, Product, persistence, configuration and user-role combinations belong to integration, end-to-end or user-acceptance frames.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 330,
          "quote": "Material combinatorial complexity is the claim-relative population of\nindependent dimensions and interactions whose combinations can change an\noutcome, violate an invariant, select another authority path or expose a\nfailure.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 327
        }
      ],
      "key": "material_combinatorial_complexity",
      "label": "Material combinatorial complexity"
    },
    {
      "conditions": [
        "The claim asks whether a declared user can obtain the exact Product-defined outcome through the supported ordinary surface."
      ],
      "definition": "The primary Product-outcome evidence frame for claims that a user can use the Product. Its subject is the exact deployed, installed or runnable form under current Product, requirement, UX, identity, policy and acceptance authority, declared role, environment and harnessed/live mode. Its manifold covers goals, entries, permissions, inputs, configuration, ordinary dependencies, declared worker/transport substitutions, visible state and outputs, refusals, recovery and acceptance interval. Coordinates bind Product/artifact identity, install, role, capability, configuration, dependency realisation, mode, data, workspace, invocation, time, outcome and scenario. Evidence includes actual supported requests/responses, visible projections, claimed durable effects, refusals, recovery, scenario records and exact subject/dependency identities. Capability requires acting as the declared user, perceiving material outcomes/refusals and detecting hidden setup or unsupported assistance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 409,
          "quote": "| capability envelope | ability to operate the Product as the declared user would, perceive the material outcome and refusal surfaces, and distinguish hidden setup or unsupported assistance |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FUser-acceptance%20frame",
          "start_line": 409
        }
      ],
      "key": "user_acceptance_frame",
      "label": "User-acceptance frame"
    },
    {
      "conditions": [],
      "definition": "Evaluates whether the exact runnable Product realises an outcome through every material interface, owner, state transition, effect, persistence, continuation, recovery and projection boundary of the complete authoritative path. Basis includes composition design, supported entry, selected owners/dependencies, ordinary runtime configuration and Product claim. The manifold includes entry-to-outcome producers/consumers, contracts, authority transitions, state, events, persistence, processes, continuation, retry, recovery, projections and competing paths. Coordinates identify artifact/install, entry, operation, definition/owner, path/edges, process, event prefix, state, configuration, dependency, result, replay and scenario. Evidence includes entry invocation, observed semantic path/authority edges, owner receipts, durable events, transitions, outputs, claimed replay/reconstruction, installed identity and negative paths. Capability requires observing the complete path without changing it, distinguishing rivals and reproducing material state/failure relations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 434,
          "quote": "| evaluation family | Does the exact Product subject realise the claimed outcome through the complete authoritative Product path, including every material interface, owner, state transition, effect, persistence, continuation, recovery and projection boundary? |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FEnd-to-end%20frame",
          "start_line": 434
        }
      ],
      "key": "end_to_end_frame",
      "label": "End-to-end frame"
    },
    {
      "conditions": [],
      "definition": "Evaluates actual participants at one declared material composition boundary against their joint contract across outcome-changing state, authority, configuration, timing, failure and recovery combinations. Basis binds the exact declaration, actual implementations or exact admitted substitutes, Product/requirement/design law and interaction population. The manifold includes both sides, shared carriers, pre/postconditions, authority/ownership, ordering, state, configuration, failure, retry, recovery, translation and competing participants. Coordinates bind participant/version, interface/carrier revision, state, configuration, dependency, interaction case, input, output, failure and evidence. Evidence comprises exchanges, admitted carriers, transitions, contract verdicts, failures, retries, recovery, combinations and participant identities. Capability requires exercising/observing the seam, detecting substitution and varying every material interaction dimension.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 457,
          "quote": "| evaluation family | Do the actual participants at one declared material composition boundary satisfy their joint contract across the combinations of state, authority, configuration, timing, failure and recovery that can change the boundary result? |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FIntegration%20frame",
          "start_line": 457
        }
      ],
      "key": "integration_frame",
      "label": "Integration frame"
    },
    {
      "conditions": [],
      "definition": "Evaluates one module-owned law across material operator, calculation-regime, state, transition, public/private boundary-class and failure combinations. Basis includes the exact module boundary, accepted ontology/design, active declared carrier inventory, owned requirements/public contracts, implementation and module-bounded decidable oracle. The manifold includes public contracts, algebras, calculations, parsers, reducers, state machines, transitions, combinators, admission predicates, conservation laws, invariants, numerical boundaries and failures. Coordinates bind module/implementation revision, law, operator/function family, state, input/boundary class, expected relation, generated case, mutation and result. Evidence includes law-derived examples, equivalence classes, available finite exhaustive cases, properties/generation, metamorphic relations, calculation/algebra oracles, boundary cases and killed internal mutations. Capability requires an independently law-derived oracle, identifying bounded combinations and distinguishing violations from implementation restatement.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 481,
          "quote": "| evaluation family | Does one module-owned law hold across its material combinations of algebraic operator, calculation regime, state, transition, public or private boundary class, and failure case? |\n| subject and basis | one exact module boundary, the accepted ontology and design, the active carrier inventory the design declares, module-owned requirements and public contracts, the implementation, and a module-bounded decidable oracle |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FUnit%20frame",
          "start_line": 480
        }
      ],
      "key": "unit_frame",
      "label": "Unit frame"
    },
    {
      "conditions": [],
      "definition": "A claim-relative index of the material combinations a frame can discriminate. It considers at least subject/claim congruence, independent dimension number/materiality, covered interaction strength, authoritative-path exactness, oracle independence/precision, realistic-fault/rival-path/historical-failure sensitivity, observability/reconstruction/reproducibility, and explicit residual combinations/invalidation. It is not inherently a scalar.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 526,
          "quote": "Testing value is indexed first by the material combinations a frame can\ndiscriminate for its exact claim, not by test, assertion, file, line,\nbranch, mock, snapshot or runner count (P2, P6). For one claim, the\ntesting-value index considers at least:",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F8.%20Combinatorial%20coverage%20and%20testing%20value",
          "start_line": 523
        }
      ],
      "key": "testing_value_index",
      "label": "Testing-value index"
    },
    {
      "conditions": [],
      "definition": "Evaluation of two distinct finite subject-relative graphs: production closure over the exact runnable Product/configuration and transitive imports, exports, package paths, switches, registries, fallbacks, consumers, generated runtime artifacts, recovery and fresh-process reconstruction; and assurance/source closure over relied-on source consumers, fixtures, proof scripts, generators, mutations and assurance tools.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 594,
          "quote": "A successor passing does not prove the predecessor removed. Technical-debt\nerasure evaluates two distinct, finite, subject-relative graphs (P3, P6):",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F9.%20Legitimate%20path%20and%20technical-debt%20erasure",
          "start_line": 593
        }
      ],
      "key": "technical_debt_erasure",
      "label": "Technical-debt erasure"
    },
    {
      "conditions": [],
      "definition": "Distinct acquisition and evaluation relations: acquire actual owner-issued subjects through exact runnable owner surfaces, validators, projections, receipts or reconstruction relations, then evaluate with an independently contract-derived oracle.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 671,
          "quote": "Acquiring the assurance subject and evaluating it are distinct relations\n(P6, P1). Where a\nclaim depends on owner-issued Product, runtime, lifecycle, admission,\nreplay or projection truth, the testing frame acquires that truth through\nthe exact runnable owner surface, validator, projection, receipt or\nreconstruction relation.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F11.%20Assurance%20subject%20acquisition%20and%20evaluation",
          "start_line": 666
        }
      ],
      "key": "assurance_subject_acquisition",
      "label": "Assurance subject acquisition and evaluation"
    },
    {
      "conditions": [],
      "definition": "Return of a testing counterexample to its earliest supported causal frontier: causally minimal violated owner relations or seam coordinates under the declared causal relation, not log or clock order. Its four exclusive domain forms are unique locus, jointly established incomparable earliest loci whose combined violation is necessary, unresolved alternative frontiers, and an unbounded frontier represented by indeterminate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 705,
          "quote": "A testing counterexample is returned to its earliest supported causal\nfrontier on the declared path. The frontier holds the causally minimal\nviolated owner relations or seam coordinates the evidence establishes;\nearliest means minimal under the declared causal relation, not first in log\nor clock order (P5, P6).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F12.%20Counterexample%20localisation",
          "start_line": 701
        }
      ],
      "key": "counterexample_localisation",
      "label": "Counterexample localisation"
    },
    {
      "conditions": [
        "Selected by governing frame configuration or admitted work authority under the exact selected basis."
      ],
      "definition": "Composite refinement urn:stdo:reference-frame:end-to-end-interface-integration:v1, resolving in urn:stdo:bounded-context:reference-frame-evaluation owned by REFERENCE_FRAME. It relates public-boundary, design, operator, owner and proof evaluation to integration, end-to-end and user-acceptance frames. It asks whether one outcome remains constructable, understandable and correctly realised across its material interface chain with sufficient context and conserved meaning, authority and cause. Design subjects bind declared roles, functional paths, dependencies, configuration and capabilities; realisation subjects bind actual participants, callable selection, supported entry/exit and exact runnable artifact/install. Both bind an independent oracle, requirements/design, exact source/workspace checkpoint, contracts and finite cases. The manifold covers producers, consumers, transformations and effect owners, seam pre/postconditions, value/reference domains, lifecycle/time, context, mutable subject, refusals, observations and visible results. Coordinates distinguish Product, artifact/install, workspace, observation, invocation, candidate, admitted result and evidence, including revisions, domains, units, cardinality, ordering, empty/null/default meaning and validity intervals.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 752,
          "quote": "`urn:stdo:reference-frame:end-to-end-interface-integration:v1` is a\ncomposite refinement whose identity resolves in\n`urn:stdo:bounded-context:reference-frame-evaluation` (owned by\nREFERENCE_FRAME) under the exact selected basis; its assurance law is\nstated here. It relates the evaluation of public boundaries, design,\noperators, owners and proof to the integration, end-to-end and\nuser-acceptance frames of §7. Like the set, it is available and is\nactivated only where the governing frame configuration or admitted work\nauthority selects it. It adds no fifth testing type, role or\nuniversal activation gate (P2, P3).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F13.%20End-to-end%20interface%20integration%20frame",
          "start_line": 743
        }
      ],
      "key": "interface_integration_refinement",
      "label": "End-to-end interface integration refinement"
    },
    {
      "conditions": [],
      "definition": "Four distinct claims: contract sufficiency asks whether every participant can determine and perform its responsibility from declared interfaces/context; boundary congruence asks whether actual selected producers, transformations and consumers preserve domains, meanings, lifecycle and authority; path realisation asks whether the exact runnable subject uses the authoritative entry-to-outcome path; user usability asks whether the ordinary human, LLM or software caller obtains the outcome using only declared context, access and supported surfaces.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 778,
          "quote": "| contract sufficiency | Can each participant determine and perform its responsibility from the declared interface and the available context? Source-grounded design evaluation may establish this claim without an implemented runtime; unresolved realisability or actor-context questions stay explicit. |\n| boundary congruence | Do the actual selected producers, transformations and consumers preserve the declared domains, meanings, lifecycle and authority? An actual-composition claim acquires both sides and their exchanges; design correspondence alone proves no implementation behaviour. |\n| path realisation | Does the exact runnable subject use the authoritative entry-to-outcome path through its material state, effect and observation boundaries? Matching output through another path is insufficient. |\n| user usability | Can the ordinary human, LLM or software caller obtain the selected outcome using only its declared context, access and supported surface? Internal success or validator-aware fixtures cannot establish this claim. |",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F13.%20End-to-end%20interface%20integration%20frame%2FClaim%20boundaries",
          "start_line": 775
        }
      ],
      "key": "interface_claims",
      "label": "Interface refinement claims"
    },
    {
      "conditions": [
        "Material computational composition or recurrence work."
      ],
      "definition": "Bounded composition of selected interface claims with evaluations of path operators, owners, reused foundations and proof, covering one complete producer-to-consumer path under DESIGN_MODULE computational-realisation and recurrence law. It binds fact establishment, every consumer, validity/invalidation, effects, retained alternatives and accumulated work, and evaluates equivalent computation across domain names without presuming semantic equivalence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 888,
          "quote": "For material computational composition or recurrence work, the selected\ninterface claims are composed with evaluations of the path's operators,\nowners, reused foundations and proof, to evaluate one complete\nproducer-to-consumer path under the design profile's computational\nrealisation and recurrence law (DESIGN_MODULE). The evaluation binds fact\nestablishment, each consumer, validity and invalidation, effects, retained\nalternatives and accumulated work. It evaluates equivalent computation\nacross different domain names without assuming semantic equivalence.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F13.%20End-to-end%20interface%20integration%20frame%2FComputational%20whole-path%20evaluation",
          "start_line": 881
        }
      ],
      "key": "computational_whole_path_evaluation",
      "label": "Computational whole-path evaluation"
    },
    {
      "conditions": [
        "A new or materially changed realisation boundary is governed by a design profile."
      ],
      "definition": "Two directed evidence chains: semantic derivation from constitutional WHAT and owning requirements through accepted ontology, declared carriers, target design and domain/sequence/state evidence to implementation and module-derived tests, reconciliation/acceptance, promotion/design-method closure; and feedback from implementation/tests through evidence, counterexamples or falsification to affected ontology/design relations. Assertion and execution provenance remain distinct.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 946,
          "quote": "The first chain is semantic derivation. The second is evidence feedback\nand cannot select or accept the affected semantic answer (P6). The two\nchains are this member's instance of parallel derivation: expected results\ncarry assertion provenance from the first chain and executions carry\nexecution provenance from the second; agreement between them is\ncompatible with a shared error, and disagreement requires diagnosis",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F14.%20Design-to-module%20evidence%20route",
          "start_line": 941
        }
      ],
      "key": "design_module_evidence_route",
      "label": "Design-to-module evidence route"
    },
    {
      "conditions": [
        "Unit tests under the design profile."
      ],
      "definition": "Module-owned proof lanes derived from realisation authority owned by DESIGN_MODULE and from module ownership evidence. Their authority is for module proof; Product UAT and acceptance meaning remain with Product authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1025,
          "quote": "Unit tests under the design profile are module-owned proof lanes. They\nderive from module ownership evidence, not from code shape alone. A unit\ntest should be traceable to (P6, P2):",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F15.%20Module-derived%20unit%20tests",
          "start_line": 1023
        }
      ],
      "key": "module_derived_unit_lane",
      "label": "Module-derived unit lane"
    },
    {
      "conditions": [
        "A boundary is governed by the design profile."
      ],
      "definition": "Confirmation at the realisation boundary, before design-method closure, of the operational lifecycle of every designed module, function, application/runtime/plugin/public/data surface and published profile function or module. It consumes SPEC_METHOD §2 phases without redefining them; its checklist detects ambiguity about ultimate intended use and is neither a release plan nor a replacement for RELEASE.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1062,
          "quote": "Every designed module, function, application surface, runtime surface,\nplugin surface, public interface, data surface, and published function or\nmodule of a profile exists inside an operational lifecycle. Under the\ndesign profile that lifecycle signal is confirmed at the realisation\nboundary before design-method closure (P2, P6). The\ncanonical operational lifecycle chain is SPEC_METHOD §2 Operational\nlifecycle sufficiency; this section consumes that chain and does not\nredefine its phases. The checklist is not a release plan and does not\nreplace RELEASE; it is an ambiguity detector for ultimate intended use.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F16.%20Module%20lifecycle%20confirmation",
          "start_line": 1054
        }
      ],
      "key": "module_lifecycle_confirmation",
      "label": "Module lifecycle confirmation"
    },
    {
      "conditions": [],
      "definition": "Subject-described Tier 1 STDO Axiomatic Calculus for Governed Symbolic Systems, a_c: domain-specific and carrier-neutral, with stable identity urn:stdo:concept:axiomatic-calculus:a-c in urn:stdo:bounded-context:axiomatic-calculus. Its member owns position/scope, signature, record shapes, AC-001–AC-020, traversals/functor kinds, interpretation/models, three layers, calculus identity, application/import/exclusion boundaries and conformance obligations. It consumes FOUNDATIONS ontology and core results without redefining them; clauses identify their requiring P0–P6 principles. Its definitions do not depend on derivation-record layout, selected interpretation, carrier, provider, runtime or repository topology.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 14,
          "quote": "Tier 1. Owns the a_c theory in full: position and scope, the signature,\nthe typed records, the laws AC-001 to AC-020, traversals and functor\nkinds, interpretation and models, the three governed layers, the law of\ncalculus identity, the application boundary, external imports, exclusions\nand the conformance obligations of this member. Consumes the ontology of\n[FOUNDATIONS §2](FOUNDATIONS.md) (subject, representation, interpretation,\ncontext, object, claim, evidence, judgment, authority, residual, basis,\nmaterial) and the core result algebra of\n[FOUNDATIONS §4 Results](FOUNDATIONS.md#results); it states laws over\nthose objects and defines none of them a second time. Each clause names\nthe principle (P0 to P6) that requires it, as\n[FOUNDATIONS §1](FOUNDATIONS.md#1-vocabulary-of-standing) requires.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/AXIOMATIC_CALCULUS.md#AXIOMATIC_CALCULUS",
          "start_line": 3
        },
        {
          "end_line": 25,
          "quote": "The STDO Axiomatic Calculus for Governed Symbolic Systems, written `a_c`,\nis this method's domain-specific, carrier-neutral constitutional calculus\nfor representing and relating governed symbolic systems. Its stable\nconcept identity is `urn:stdo:concept:axiomatic-calculus:a-c`. This member\nowns that concept in the bounded context\n`urn:stdo:bounded-context:axiomatic-calculus`. Both identifiers are\ndeclared identities and do not change with the carrier or the directory\nthat publishes them (P3).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/AXIOMATIC_CALCULUS.md#AXIOMATIC_CALCULUS%2F1.%20Position",
          "start_line": 18
        }
      ],
      "key": "subject_axiomatic_calculus",
      "label": "Subject-described a_c calculus"
    },
    {
      "conditions": [],
      "definition": "An interpreted model a_c.X is downstream of a_c plus exact subject X. A carrier a_c.X.C encodes that model with an exact accepted semantic judgment J_X and exact carrier C. Calculus, interpreted model and encoded carrier have separate content identities and proof boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 57,
          "quote": "The calculus, an interpreted model and an encoded carrier are distinct\ngoverned layers with separate content identities and proof boundaries\n(§7). A layer becomes a released Product only through separately\nauthorised Product acceptance and release. Neither interpretation nor\nencoding can redefine the calculus (P6).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/AXIOMATIC_CALCULUS.md#AXIOMATIC_CALCULUS%2F1.%20Position",
