  "constraints": [
    {
      "applies_to_keys": ["scenario_bundle", "significant_paths"],
      "conditions": ["A requirement claims meaningful system behaviour."],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 260,
          "quote": "Features are not proved by isolated assertions alone. Where a requirement\nclaims meaningful system behaviour, the proving surface should be a scenario\nbundle or an equivalent ordered set of test cases that exercises that\nbehaviour through a coherent sequence rather than as disconnected\nfragments (P2, P6).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F4.%20Scenario%20bundle",
          "start_line": 256
        }
      ],
      "key": "coherent_scenario_proof",
      "statement": "Isolated assertions alone do not prove features. The proving surface should use a scenario bundle or equivalent ordered cases exercising coherent behaviour. Scenarios and use cases force operational intent/design to expose boundaries, sequences, actors, controls and outcomes; the significant paths they identify must be exercised.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["installed_dev_proof"],
      "conditions": ["The system has an installable or runnable development form."],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 285,
          "quote": "proof should prefer a fresh sandbox or equivalent isolated environment, an\ninstalled or built development artifact, and execution through the same\ndeclared entry, control and runtime surfaces the real product uses. Direct\nsource-level or unit-level checks may stay useful; they do not replace\ninstalled-dev proof of the system under test (P6; SPEC_METHOD §6 for the\ninstall and development-product roles).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F5.%20Installed%20dev%20proof",
          "start_line": 280
        }
      ],
      "key": "installed_proof_lane",
      "statement": "The decisive lane runs against an installed development target, not solely the source tree. It should prefer fresh isolation, an installed/built artifact and the Product's declared entry/control/runtime surfaces. Useful source/unit checks do not replace this proof.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["significant_paths"],
      "conditions": [],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 304,
          "quote": "If the significant paths are not declared, scenario coverage cannot be\njudged. If they are declared and not exercised, the behaviour is not fully\nproved (P6; EVALUATION §1, a claim's scope cannot exceed its evaluated\nevidence).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F6.%20Significant%20path%20coverage",
          "start_line": 301
        }
      ],
      "key": "significant_path_coverage_requirement",
      "statement": "The proving surface declares and exercises meaningful paths intentionally; exhaustive proof does not require every possible branch in every file. Undeclared paths make scenario coverage unjudgeable; declared but unexercised significant paths leave behaviour not fully proved. Claim scope cannot exceed evaluated evidence. The listed path classes are usual and relevance-dependent, not a universal exhaustive checklist.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["testing_frame", "authoritative_product_path", "material_combinatorial_complexity"],
      "conditions": [],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 325,
          "quote": "Producing an expected output through a bypass, an obsolete executor, a\ntest-only seam, an undeclared fallback or a competing authority falsifies\npath conformance even when the output value is equal (P6, P3).",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 323
        }
